<?phpnamespace app\common\model;/** * 订单收货地址模型 */class OrderAddress extends BaseModel{    // 定义表名    protected $name = 'order_address';    protected $updateTime = false;    // 定义主键    protected $pk = 'order_address_id';    // 追加字段    protected $append = [];    /**     * 显示性别     */    public function getGenderAttr($value)    {        $status = [0 => '未知', 1 => '先生', 2 => '女士'];        return ['text' => $status[$value], 'value' => $value];    }}